"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-0999-01-01:0":{"b": ["نون نوك ثا: مرحلة العصر البرونزي (التسلسل الزمني القصير)", "1ed767d3"], "d": ["مقبرة العصر البرونزي في شمال شرق تايلاند التي نقّب فيها بايارد في الستينيات؛ وفي إعادة التأريخ لدى هيغام وآخرين 2015 تمتد المدافن البرونزية من القرن 9 ق.م (MP 3: 840-800 ق.م) إلى القرنين 8-6 ق.م.", "2701846a"]},
"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-1199-01-01:0":{"b": ["سانغاناكالو-كوبغال: تُهجر (تقريبًا)", "7a529c82"], "d": ["قرى العصر الحجري الحديث المتأخر على قمم تلال الغرانيت في حوض تونغابهادرا؛ نمو بين 1400-1200 ق.م، وهجر القرى التلية كلها تقريبًا نحو 1200 ق.م (الحديد شبه معدوم).", "99d2b08b"]},
"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-1399-01-01:0":{"b": ["سانغاناكالو-كوبغال: توسع قرى التلال (الانتقال من العصر الحجري الحديث المتأخر إلى العصر الميغاليثي)", "479ad8a5"], "d": ["قرى العصر الحجري الحديث المتأخر على قمم تلال الغرانيت في حوض تونغابهادرا؛ نمو بين 1400-1200 ق.م، وهجر القرى التلية كلها تقريبًا نحو 1200 ق.م (الحديد شبه معدوم).", "99d2b08b"]},
"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-1499-01-01:0":{"b": ["خوك فانوم دي: ينتهي الاستيطان", "fec9171f"], "d": ["مستوطنة ومقبرة من العصر الحجري الحديث عند مصب خليج بانغ باكونغ، ذات سبع مراحل دفن (~20 جيلًا)؛ لا برونز، ومركز لتجارة الخرز المصنوع من الأصداف.", "6daab256"]},
"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-1509-01-01:0":{"b": ["بان تشيانغ: أول دفن مؤرَّخ (كولاجين العظام، التسلسل الزمني القصير)", "0dab4585"], "d": ["مستوطنة ومقبرة لمزارعي الأرز من العصر الحجري الحديث في شمال شرق تايلاند؛ بحسب تسلسل هيغام القصير مزارعو الأرز في القرن 16 ق.م، والانتقال إلى العصر البرونزي نحو 1000 ق.م، والعصر الحديدي في النصف الثاني من الألفية الأولى ق.م.", "b85d0aad"]},
"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-1799-01-01:0":{"b": ["بان نون وات: مرحلة العصر الحجري الحديث 1: يستقر مزارعو الأرز", "518b82cd"], "d": ["موقع محاط بخندق، وهو أطول تتابع متصل في جنوب شرق آسيا من العصر الحجري الحديث إلى أواخر العصر الحديدي؛ 75 تاريخًا بالكربون المشع (أصداف، فحم، أرز مقشور، عظام) مع نحو 700 مدفن. العصر البرونزي: BA1 1050-1000، BA2 1000-900، BA3 900-800، BA4 800-700، BA5 700-420 ق.م؛ العصر الحجري الحديث 2 1250-1050.", "8db1d633"]},
