"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1324-01-01:0":{"b": ["كامغوت (مستوطنة لابيتا المبكرة)، جزيرة بابازي، جزر أنير: كامغوت (أنير): استيطان لابيتا المبكر", "309ead6a"], "d": ["مستوطنة لابيتا مبكرة على حافة بحيرة ساحلية (ببيوت على أوتاد) في جزر أنير؛ واقتصاد جُلبت إليه الخنازير والكلاب (وتؤكده هوراكس وآخرون 2024 ببيض الطفيليات).", "11830db9"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1346-01-01:0":{"b": ["مجمّع حجر الأيل-خيريغسور (Deer Stone-Khirigsuur Complex)، منغوليا: تبدأ المنشآت الجنائزية للخيريغسور (حجر الأيل)", "c3bc7513"], "d": ["نُصُب حجر الأيل المنتصبة ومنشآت الخيريغسور الجنائزية المربعة/المستديرة المحاطة بالحجارة؛ ومنذ نحو 1200 ق.م تصبح الخيول جزءًا لا يتجزأ من هذه المنشآت (أثر الركوب).", "151e9ef5"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1449-01-01:0":{"b": ["ثقافة لابيتا - بداية أرخبيل بسمارك: تظهر لابيتا في أرخبيل بسمارك", "76e4a532"], "d": ["يظهر فخار لابيتا المختوم بالأسنان (dentate-stamped) في أرخبيل بسمارك؛ ومنه ينتشر جنوبًا شرقًا نحو أوقيانوسيا البعيدة.", "2303b836"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-14961-01-01:0":{"b": ["أفونتوفا غورا-2 (AG-2)، ينيسي، قرب كراسنويارسك: أفونتوفا غورا-2: استيطان سيبيريا في العصر الحجري القديم الأعلى (خارج الأفق)", "c4ed402c"], "d": ["الفرد AG-2 من مجمّع أفونتوفا غورا في العصر الحجري القديم الأعلى على ضفة ينيسي؛ وله بصمة وراثية مشابهة لـ MA-1 — يدل على أن سيبيريا كانت مأهولة طوال أقصى امتداد جليدي.", "a6f3a1d6"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1499-01-01:0":{"b": ["المراكز الاحتفالية في بامبا دي لاس هاماكاس (خيكيتيبيكي، التكويني): يبدأ طور هاماكاس (خيكيتيبيكي)", "535096ec"], "d": ["سلسلة من المراكز الاحتفالية التكوينية في وسط وادي خيكيتيبيكي؛ ويتحول موضع المراكز شرقًا مع الزمن. طور هاماكاس 1500-1250، وتيمبلادورا 1250-800 (الهجر نحو 800)، ولتشوساس 800-550 ق.م معايَر.", "37bdf93d"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1509-01-01:0":{"b": ["سيتشين ألتو: سيتشين ألتو: استيطان ما قبل هالداس", "e077b503"], "d": ["مجمّع احتفالي كبير من فترة موكسيكي/هالداس في وادي كاسما؛ وأقدم الأبنية المعروفة نحو 1600-1400 ق.م، وواجهة موكسيكي B المصبوغة نحو 1450/1400، وتمتد تواريخ فترة هالداس (1400-1000) إلى نحو 1100-920.", "12e4a1ea"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1549-01-01:0":{"b": ["سيتشين باخو: ينتهي الاستيطان التكويني في سيتشين باخو", "dc7171bc"], "d": ["أقدم عمارة لبنية ضخمة في وادي كاسما ذات ساحة دائرية غائرة؛ وتسلسل البناء منذ نحو 3400 ق.م، وينتهي الاستيطان التكويني نحو 1550-1470 ق.م.", "27122c02"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-1624-01-01:0":{"b": ["سان خوسيه موغوتي: قرية ومركز احتفالي ما بعد روساريو وهجره: تأسيس قرية سان خوسيه موغوتي", "abd870ca"], "d": ["في وادي سان خوسيه موغوتي (أواكساكا، فرع إتلا) قرية مساحتها 7 هكتارات على الأقل في طور تييراس لارغاس (1500-1150 ق.م)؛ وفي طور روساريو مركز مجموعة من 18-23 قرية. وفي نهاية روساريو رحل نحو 95% من السكان للمشاركة في تأسيس مونتي ألبان؛ وهُجر المركز البالغ مساحته 40 هكتارًا في Mound 1 حتى مطلع مونتي ألبان II (100 ق.م).", "8b8229e9"]},
